// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        uint256 v = bound(uint256(amount), 0, type(uint96).max);
        vm.deal(actor, v);
        uint256 before = c.getBalance(actor);
        vm.prank(actor);
        c.addToBalance{value: v}();
        assertEq(c.getBalance(actor), before + v);
    }
}
